namespace TwoNineteenVolts.Venue.Domain.Spots;

// Anything switched by one relay channel: a billiard table, a tennis table, a gaming PC.
// Device and channel are both set (mapped) or both empty (unmapped).
public class Spot(string code, string name, int? deviceId, int? channel, DateTime createdAt)
{
    public int Id { get; private set; }

    // Printed in the QR sticker link; generated by the app.
    public string Code { get; private set; } = code;

    public string Name { get; private set; } = name;

    public int? DeviceId { get; private set; } = deviceId;

    // Numbered from 1, as printed on the boards.
    public int? Channel { get; private set; } = channel;

    // Archived spots are kept for statistics and never come back.
    public bool IsArchived { get; private set; }

    public DateTime CreatedAt { get; private set; } = createdAt;

    public bool IsMapped => DeviceId is not null;

    public void Rename(string name) => Name = name;

    public void MapTo(int deviceId, int channel)
    {
        DeviceId = deviceId;
        Channel = channel;
    }

    public void Unmap()
    {
        DeviceId = null;
        Channel = null;
    }

    public void ChangeCode(string code) => Code = code;

    // Frees the channel for another spot.
    public void Archive()
    {
        IsArchived = true;
        Unmap();
    }
}
